create or replace function public.recover_cut_file_generated(p_cut_id uuid,p_request_id uuid) returns jsonb language plpgsql security definer set search_path=public,app_private,pg_temp as $$
declare v_cut public.inventory_cuts%rowtype;v_file public.generated_files%rowtype;
begin perform app_private.require_generator();select * into v_cut from public.inventory_cuts where id=p_cut_id for update;select * into v_file from public.generated_files where cut_id=p_cut_id and file_type='CUT_XLSX';if not found or v_cut.status<>'ERROR' or v_cut.generation_request_id<>p_request_id or v_file.sha256<>v_cut.file_hash or v_file.file_name<>v_cut.file_name then raise exception 'Verified artifact recovery is not allowed' using errcode='23514';end if;update public.inventory_cuts set status='FILE_GENERATED',generation_error=null where id=p_cut_id;return jsonb_build_object('status','FILE_GENERATED');end $$;
revoke all on function public.recover_cut_file_generated(uuid,uuid) from public,anon,authenticated;
